package org.humanjourney.core.mapfeature;
import java.util.*;
import java.nio.file.*;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.io.TempDir;
import static org.junit.jupiter.api.Assertions.*;
import com.electronwill.nightconfig.core.CommentedConfig;
import com.electronwill.nightconfig.core.file.CommentedFileConfig;
import org.humanjourney.core.mapfeature.client.*;
import org.humanjourney.core.geography.client.GeographyClientConfig;
import org.humanjourney.core.geography.map.*;
import org.humanjourney.core.geography.map.client.*;
class FeaturePresentationTest {
 @TempDir Path temp;
 @Test void defaultAndIndependentModeCycle(){assertEquals("hover",GeographyClientConfig.FEATURE_MODE.getDefault());assertEquals(true,GeographyClientConfig.FEATURES_ENABLED.getDefault());var mode=FeatureMode.HOVER;for(String s:List.of("hover","all","off")){assertEquals(s,mode.id());assertTrue(FeatureMode.valid(s));mode=mode.next();}assertEquals(FeatureMode.HOVER,mode);assertEquals("HJ Features: Hover",mode.label());assertEquals(FeatureMode.HOVER,FeatureMode.parse("bad"));assertFalse(FeatureMode.valid("locals"));assertEquals(.35,GeographyClientConfig.FEATURE_OPACITY.getDefault());assertEquals(.85,GeographyClientConfig.FEATURE_HOVER_OPACITY.getDefault());}
 @Test void featureModeSaveAndReloadDoesNotAlterBordersPreference(){var file=temp.resolve("client.toml");try(var c=CommentedFileConfig.builder(file).sync().build()){c.load();GeographyClientConfig.SPEC.setConfig(c);try{GeographyClientConfig.mode(BoundaryMode.LOCALS);GeographyClientConfig.featureMode(FeatureMode.ALL);assertEquals(BoundaryMode.LOCALS,GeographyClientConfig.mode());}finally{GeographyClientConfig.SPEC.setConfig(null);}}try(var c=CommentedFileConfig.builder(file).sync().build()){c.load();GeographyClientConfig.SPEC.setConfig(c);try{assertEquals(FeatureMode.ALL,GeographyClientConfig.featureMode());assertEquals(BoundaryMode.LOCALS,GeographyClientConfig.mode());}finally{GeographyClientConfig.SPEC.setConfig(null);}}}
 @Test void invalidFeatureModeUsesHoverWithoutChangingGeography(){var c=CommentedConfig.inMemory();c.set("world_map_features.world_map_feature_mode","bad");c.set("world_map_geography.world_map_boundary_mode","all");GeographyClientConfig.SPEC.correct(c);assertEquals("hover",c.get("world_map_features.world_map_feature_mode"));assertEquals("all",c.get("world_map_geography.world_map_boundary_mode"));}
 @Test void hoverAllAndOffSelectOnlyAppropriateDiscoveredGeometry(){var data=FeatureModelTest.catalog(FeatureModelTest.polygon("sea",1),FeatureModelTest.line("river",2));var projected=FeatureCatalog.project(data,Set.of("sea"));var snapshot=new ClientFeatureState.Snapshot(null,projected,new FeatureIndex(projected.values()));var view=FeatureIndex.around(50,50,60);var selection=snapshot.index().hover(FeatureModelTest.DIM,50,50,5);assertEquals("sea",FeaturePresentation.selected(snapshot,FeatureModelTest.DIM,FeatureMode.HOVER,selection).id());assertTrue(FeaturePresentation.persistent(snapshot.index(),FeatureModelTest.DIM,view,FeatureMode.HOVER).isEmpty());assertEquals(1,FeaturePresentation.persistent(snapshot.index(),FeatureModelTest.DIM,view,FeatureMode.ALL).size());assertNull(FeaturePresentation.selected(snapshot,FeatureModelTest.DIM,FeatureMode.OFF,selection));assertTrue(FeaturePresentation.persistent(snapshot.index(),FeatureModelTest.DIM,view,FeatureMode.OFF).isEmpty());assertTrue(FeaturePresentation.persistent(snapshot.index(),"minecraft:the_nether",view,FeatureMode.ALL).isEmpty());}
 @Test void polylineHitToleranceIsFiveGuiPixelsAcrossZoomAndScale(){var line=FeatureModelTest.parse(FeatureModelTest.line("river",0)).view();var index=new FeatureIndex(List.of(line));for(double gui:List.of(1D,2D,4D))for(double zoom:List.of(.02D,1D,128D)){var transform=new MapViewTransform(1000,600,gui,50,50,zoom);double tolerance=FeaturePresentation.HIT_GUI_PIXELS*gui/zoom;assertNotNull(index.hover(FeatureModelTest.DIM,50,50+tolerance*.99,tolerance).feature());assertNull(index.hover(FeatureModelTest.DIM,50,50+tolerance*1.01,tolerance).feature());assertEquals(5,transform.screen(50,50+tolerance).y()-transform.screen(50,50).y(),1e-7);}}
 @Test void dualControlsNeverOverlapEachOtherCompassOrOccupiedWidgets(){for(int width:List.of(320,640,1000,1920))for(int height:List.of(240,480,1080)){var occupied=List.of(new BoundaryControlLayout.Rect(0,height-30,width,30));var pair=BoundaryControlLayout.placePair(width,height,occupied).orElseThrow();assertFalse(pair.get(0).overlaps(pair.get(1)));for(var r:pair){assertFalse(r.overlaps(BoundaryControlLayout.compass(width,height)));assertFalse(r.overlaps(occupied.getFirst()));assertTrue(r.x()>=8&&r.y()>=8);}}}
 @Test void noSafeControlPlacementDoesNotCoverNativeUi(){assertTrue(BoundaryControlLayout.placePair(1000,600,List.of(new BoundaryControlLayout.Rect(0,0,1000,600))).isEmpty());assertTrue(BoundaryControlLayout.placePair(100,40,List.of()).isEmpty());}
 @Test void featureRenderingAndTooltipAreIsolatedAndUseProtectedCursorPosition()throws Exception{var root=Path.of(System.getProperty("humanjourney.projectDir"));String s=Files.readString(root.resolve("src/main/java/org/humanjourney/core/integration/xaero/client/Xaero13913Adapter.java"));assertTrue(s.indexOf("FeaturePresentation.persistent")<s.indexOf("for(var layer:layers)"));assertTrue(s.indexOf("for(var layer:layers)")<s.indexOf("if(feature!=null)featureOutline"));assertTrue(s.contains("if(feature!=null)featureTooltip"));assertTrue(s.contains("else if(geographyEnabled"));String tip=s.substring(s.indexOf("private static void featureTooltip"),s.indexOf("private static String fit"));assertTrue(tip.contains("mouseX+12"));assertTrue(tip.contains("mouseY+12"));assertTrue(tip.contains("screenWidth-w-2"));String ui=Files.readString(root.resolve("src/main/java/org/humanjourney/core/integration/xaero/client/XaeroBoundaryControl.java"));assertTrue(ui.contains("placePair"));assertTrue(ui.contains("featureMode().next()"));assertFalse(ui.contains("FeatureNetwork"));assertFalse(ui.contains("MapNetwork"));}
}
